steps.code:
# Parse the schedule to compute total work minutes
import re

content = note['content']
work_minutes = 0
for line in content.split('\n'):
    if 'Work hours' in line:
        # Extract duration and unit
        match = re.search(r'Work hours\s*=>\s*([\d.]+)\s*(minutes|hours|hour|minute|min|hrs?)?', line)
        if match:
            value = float(match.group(1))
            unit = match.group(2) or 'minutes'
            if unit.startswith('hour') or unit == 'hrs' or unit == 'hr':
                work_minutes += value * 60
            else:
                work_minutes += value
print("Total work minutes:", work_minutes)

